const state={step:0,answers:{},selected:null};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={work:'<rect x="5" y="10" width="25" height="20" rx="3"/><path d="M12 10V5h11v5M5 18h25M16 17v5h5v-5"/>',star:'<path d="m18 3 5 10 11 2-8 8 2 11-10-5-10 5 2-11-8-8 11-2Z"/>',spark:'<path d="m18 3 4 11 11 4-11 4-4 11-4-11-11-4 11-4ZM29 1v8M25 5h8"/>',compass:'<circle cx="18" cy="18" r="14"/><path d="m24 11-4 10-9 4 4-10Z"/>',chat:'<path d="M5 5h26v20H17L9 32v-7H5ZM11 12h14M11 18h9"/>'};
function icon(key){return `<svg class="icon" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round">${icons[key]||icons.compass}</svg>`}
function choices(items,multi=false){return `<div class="options">${items.map(([v,t,d,k],i)=>`<button type="button" class="option ${items.length%2&&i===items.length-1?'wide':''} ${(multi?(state.selected||[]).includes(v):state.selected===v)?'selected':''}" data-value="${esc(v)}" aria-pressed="${multi?(state.selected||[]).includes(v):state.selected===v}">${icon(k)}<span><strong>${esc(t)}</strong><small>${esc(d)}</small></span><span class="radio"></span></button>`).join('')}</div>`}
const paths=[['H-1B','H-1B 工作签证','专业职业 · 雇主支持','work'],['EB-1A','EB-1A 杰出人才','职业成就 · 永久居留','star'],['O-1','O-1 杰出能力','专业影响力 · 在美工作','spark'],['探索方向','还不确定','一起探索适合的方向','compass']];
function fields(html){return `<form id="step-form">${html}</form>`}function field(name,label,type='text',placeholder=''){return `<label class="field">${label}<input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(state.answers[name])}" required maxlength="200"></label>`}
function branch(){return state.answers.path==='H-1B'?{title:'聊聊你的工作机会。',hint:'这能帮助律师了解雇主支持情况。不确定也没关系。',items:[['已有雇主支持','已有雇主支持','已获得工作机会，或正在美国工作','work'],['正在找工作','正在寻找机会','尚未确认提供支持的雇主','compass'],['需要讨论','情况比较特殊','转雇主、延期，或其他情况','chat']]}:{title:'哪些成就最能代表你？',hint:'可以多选。这里只收集线索，具体证据由律师进一步审核。',items:[['奖项','专业奖项','行业、国家或国际认可','star'],['发表与报道','发表与媒体报道','论文、作品或有关你的报道','chat'],['评审与贡献','评审与原创贡献','担任评审，或有重要专业贡献','spark'],['领导与薪酬','领导角色与薪酬','关键岗位，或行业内较高薪酬','work'],['暂不确定','暂不确定','希望和律师一起梳理','compass']]}}
function render(){const s=state.step;const labels=['开始了解你','你的基本情况','你的专业背景','你的时间安排','领取免费摘要','你的下一步'];$('#step-label').textContent=labels[s];$('#step-count').textContent=`0${s+1} / 06`;$('#progress').style.width=`${(s+1)/6*100}%`;let body='';state.selected=s===0?state.answers.path:s===2?(state.answers.path==='H-1B'?state.answers.employer:state.answers.achievements||[]):s===3?state.answers.timeline:null;
if(s===0)body=`<div class="kicker">很高兴认识你</div><h2>你想从哪条移民路径开始？</h2><p class="hint">先选一个方向。还没有答案？我们也可以一起探索。</p>${choices(paths)}`;
if(s===1)body=`<h2>先简单认识一下你。</h2><p class="hint">不需要敏感证件信息，告诉我们目前的大致情况即可。</p>${fields(field('name','怎么称呼你？','text','你的名字或常用称呼')+`<label class="field">你目前在哪里？<select name="location" required><option value="">请选择</option>${['美国境内','中国大陆','其他国家或地区'].map(v=>`<option ${state.answers.location===v?'selected':''}>${v}</option>`).join('')}</select></label>`+field('status','目前的签证或居留身份','text','例如 F-1、H-1B、境外，或不确定'))}`;
if(s===2){const b=branch();body=`<h2>${b.title}</h2><p class="hint">${b.hint}</p>${choices(b.items,state.answers.path!=='H-1B')}${fields(field('profession','你的专业领域或职位','text','例如：软件工程师、生物研究、视觉设计'))}`}
if(s===3)body=`<h2>你希望什么时候迈出下一步？</h2><p class="hint">帮助律师了解你的安排；如果有身份到期日，请在备注中说明。</p>${choices([['尽快','尽快开始','有近期安排或需要尽快沟通','spark'],['3个月内','未来 3 个月','正在计划下一步','work'],['半年内','未来半年','希望提前做好准备','compass'],['先了解','先了解一下','暂时没有具体时间表','chat']])}${fields(`<label class="field">还有什么希望律师了解的？（选填）<textarea name="notes" maxlength="2000" placeholder="例如：身份到期时间、工作变动、家属安排……">${esc(state.answers.notes)}</textarea></label>`)}`;
if(s===4)body=`<h2>把你的故事，整理成下一步。</h2><p class="hint">免费生成「移民咨询准备摘要」，包含背景记录、材料准备清单和待向律师确认的问题。</p><div class="summary"><h3>你的资料概览</h3><dl><dt>称呼</dt><dd>${esc(state.answers.name)}</dd><dt>关注方向</dt><dd>${esc(state.answers.path)}</dd><dt>专业领域</dt><dd>${esc(state.answers.profession)}</dd><dt>计划时间</dt><dd>${esc(state.answers.timeline)}</dd></dl></div>${fields(field('email','你的联系邮箱','email','you@example.com')+`<label class="check"><input name="consent" type="checkbox" required ${state.answers.consent?'checked':''}><span>我同意本次使用填写的信息生成摘要，并理解该摘要未经律师审核，不构成法律意见或委托关系。演示版信息仅保留在当前页面内存中。</span></label>`)}`;
if(s===5)body=`<div class="kicker success">✧ 已整理完成</div><h2>${esc(state.answers.name)}，下一步更清晰了。</h2><p class="hint">你的免费咨询准备摘要已就绪。可下载保存，并在正式咨询时提供给律师。</p><div class="summary"><h3>移民咨询准备摘要</h3><dl><dt>关注方向</dt><dd>${esc(state.answers.path)}</dd><dt>审核状态</dt><dd>等待持牌律师独立评估</dd><dt>联系邮箱</dt><dd>${esc(state.answers.email)}</dd></dl></div><h3 style="font-size:14px;margin-top:24px">可以先准备这些材料</h3><ul class="checklist">${materials().map(t=>`<li>${t}</li>`).join('')}</ul><button class="primary" id="download">下载免费摘要</button><button class="back" id="print">打印 / 保存 PDF</button><p class="footnote">本演示未向律所提交资料，也未发送邮件。</p>`;
$('#content').innerHTML=`<div class="fade"><div class="guide"><div class="avatar">✳</div><div><strong>我是你的旅程向导，Silky</strong><small>一步一步，了解你的可能性</small></div></div>${body}<p class="error" role="alert" id="error"></p>${s<5?`<div class="actions"><button class="primary" id="next">${s===4?'生成免费摘要':'继续'}</button>${s>0?'<button class="back" id="back">返回上一步</button>':''}</div><p class="footnote">${s===0?'你的选择仅用于引导问题，不代表资格判断。':'信息仅在当前页面中暂存，刷新后清除。'}</p>`:''}</div>`;
$('#content').querySelectorAll('[data-value]').forEach(el=>el.onclick=()=>{const v=el.dataset.value;if(s===2&&state.answers.path!=='H-1B'){let a=state.selected||[];state.selected=v==='暂不确定'?['暂不确定']:a.includes(v)?a.filter(x=>x!==v):[...a.filter(x=>x!=='暂不确定'),v]}else state.selected=v;$('#content').querySelectorAll('[data-value]').forEach(e=>{const yes=Array.isArray(state.selected)?state.selected.includes(e.dataset.value):e.dataset.value===state.selected;e.classList.toggle('selected',yes);e.setAttribute('aria-pressed',yes)})});
if($('#next'))$('#next').onclick=next;if($('#back'))$('#back').onclick=()=>{saveFields();state.step--;render()};if($('#step-form'))$('#step-form').onsubmit=e=>{e.preventDefault();next()};if($('#download'))$('#download').onclick=download;if($('#print'))$('#print').onclick=printReport;}
function saveFields(){const f=$('#step-form');if(f)for(const[k,v]of new FormData(f))state.answers[k]=v;}
function next(){const s=state.step;const f=$('#step-form');if(f&&!f.reportValidity())return;if([0,2,3].includes(s)&&(!state.selected||(Array.isArray(state.selected)&&!state.selected.length))){$('#error').textContent='请选择一个选项，再继续。';return}saveFields();if(s===0){if(state.answers.path!==state.selected){delete state.answers.achievements;delete state.answers.employer}state.answers.path=state.selected}if(s===2)state.answers[state.answers.path==='H-1B'?'employer':'achievements']=state.selected;if(s===3)state.answers.timeline=state.selected;state.step++;render()}
function materials(){return state.answers.path==='H-1B'?['更新后的个人简历及学历资料','职位说明与雇主支持情况说明','现有身份文件与到期日期（咨询时提供）']:['个人简历及专业经历时间线','奖项、发表、媒体报道等成就目录','评审、原创贡献或关键岗位的证明线索']}
function report(){const a=state.answers;return `SILKEN PATH · 移民咨询准备摘要\n生成日期：${new Date().toLocaleDateString('zh-CN')}\n\n本文件仅按用户自述整理，未经律师审核，不构成法律意见、资格认定或委托关系。\n\n称呼：${a.name}\n邮箱：${a.email}\n所在地区：${a.location}\n当前身份：${a.status}\n关注方向：${a.path}\n专业领域：${a.profession}\n背景线索：${a.employer||(a.achievements||[]).join('、')}\n时间安排：${a.timeline}\n补充说明：${a.notes||'无'}\n\n建议整理的资料\n${materials().map((t,i)=>`${i+1}. ${t}`).join('\n')}\n\n咨询时待确认\n1. 结合具体事实，哪些申请方向值得进一步评估？\n2. 目前证据有哪些缺口，需要如何补充？\n3. 现有身份及时间安排是否需要优先处理？\n4. 律师服务范围、预计费用与后续步骤是什么？\n\n审核状态：待持牌律师独立评估\n本演示未向任何律所提交信息。`}
function download(){const url=URL.createObjectURL(new Blob(['\ufeff'+report()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Silken-Path-咨询准备摘要.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printReport(){const w=window.open('','_blank');if(!w){$('#error').textContent='请允许打开打印窗口，或下载文本摘要。';return}w.document.write(`<html lang="zh-CN"><head><title>移民咨询准备摘要</title><style>body{padding:40px;font:15px/1.9 sans-serif}pre{white-space:pre-wrap;font:inherit}</style></head><body><pre>${esc(report())}</pre></body></html>`);w.document.close();w.print()}
function show(title,text){$('#dialog-content').innerHTML=`<h2>${title}</h2>${text}`;$('#dialog').showModal()}
$('#about').onclick=()=>show('从一个对话开始','<p>选择方向 → 介绍背景 → 补充经历 → 确认时间 → 生成免费咨询准备摘要。</p><p>H-1B 分支收集雇主线索；EB-1A、O-1 与探索分支收集专业成就。最终由持牌律师决定是否接案和如何提供法律服务。</p>');$('#privacy').onclick=()=>show('你的信息，由你掌握','<p>当前为交互演示。填写内容只保存在当前页面内存中，不上传服务器、不使用本地存储，刷新或关闭页面即清除。摘要由浏览器本地生成。</p><p>请勿填写护照号码、社会安全号码或上传原始证件。未来接入律所系统时，应先展示对应隐私政策和数据授权。</p>');$('.close').onclick=()=>$('#dialog').close();render();
